        for (int i = 1; i <= n; i++) {
            int val = scanner.nextInt();
            if (val == 1) {
                ones.add(i);
            }
        }

        long ans = 0;
        int k = ones.size();
        for (int i = 0; i < k; i++) {
            long prev = (i == 0) ? 0 : ones.get(i - 1);
            long next = (i == k - 1) ? n + 1 : ones.get(i + 1);
            long curr = ones.get(i);

            long leftChoices = curr - prev;
            long rightChoices = next - curr;

            ans += leftChoices * rightChoices;
        }

        System.out.println(ans);
    }
